// Code generated by internal/config/schemadoc; DO NOT EDIT.

package config

// Schema documents every config key, in file order.
var Schema = []SchemaField{
	{Key: "site", Type: "string", Doc: "Site is the Zulip base URL, e.g. https://zulip.example.com."},
	{Key: "site_aliases", Type: "[]string", Doc: "SiteAliases are OTHER host names the same realm answers to. A realm is routinely reachable under more than one name — a Tailscale or LAN name the relay dials, and a public vanity domain the humans browse. Attachment ingestion accepts an ABSOLUTE `https://<host>/user_uploads/…` link only when <host> is one of ours, so a link someone pasted from \"Copy link\" in a browser on the OTHER name is otherwise silently not an attachment. Composer-attached files use relative paths and are unaffected. Entries may be bare hosts (\"zulip.example.com\", with an optional :port) or full URLs; only the host part is used."},
	{Key: "public_url", Type: "string", Doc: "PublicURL is the realm root that humans open, e.g. https://zulip.example.com/. Set it when Site is an internal name (a Tailscale or LAN host) that a phone outside that network cannot reach. Links the agent gives to humans use it. Unset means Site."},
	{Key: "bot_email", Type: "string", Doc: "BotEmail is the relay bot's e-mail, half of its HTTP Basic credentials. ZULIP_EMAIL overrides it."},
	{Key: "bot_api_key", Type: "string", Doc: "BotAPIKey is the relay bot's API key, the other half. ZULIP_API_KEY overrides it; prefer the environment."},
	{Key: "channels", Type: "[]string", Doc: "Channels lists the Zulip channels the relay serves, by name or by numeric id. Names are resolved to ids once at startup, and the resolved set doubles as the channel allowlist: the relay never answers anywhere else."},
	{Key: "ambient_channels", Type: "[]string", Doc: "AmbientChannels lists channels the relay engages WITHOUT an @-mention: in these, every message opens or continues the topic's conversation, exactly as a DM does. Elsewhere a new topic must @-mention the bot to summon it (the mention is the membership record). Entries are names or ids, resolved like Channels, and must also be served (via `channels` or \"*\"). Same exposure as DMs: anyone who can post in an ambient channel can summon an agent with a shell, no mention required. allowed_user_ids still gates it."},
	{Key: "autotopic_channels", Type: "[]string", Doc: "AutotopicChannels lists channels where a \"general chat\" message — Zulip 11's empty topic (\"\") — is MOVED to a freshly named topic before the relay answers, so the conversation happens there instead of in the channel's undifferentiated feed. Entries are names or ids, resolved like Channels, and must also be served (via `channels` or \"*\"). Everywhere else general chat behaves exactly as any other topic."},
	{Key: "dms", Type: "bool", Doc: "DMs enables direct-message conversations: 1:1 and group DMs with the bot. Default FALSE — serving DMs is an explicit decision. The `channels` allowlist cannot gate a DM (a DM is in no channel), so with DMs on, anyone in the realm who is not excluded by allowed_user_ids can open a session with an agent that has a shell. Same reasoning as requiring `channels` to be set explicitly: \"everything\" must be asked for, never defaulted into. allowed_user_ids applies to DMs unchanged."},
	{Key: "allowed_user_ids", Type: "[]int64", Doc: "AllowedUserIDs, if non-empty, restricts who the relay answers, in channels and in DMs alike."},
	{Key: "update_owner_ids", Type: "[]int64", Doc: "UpdateOwnerIDs lists the Zulip user ids allowed to run `!update` (acp-kit/update). Empty disables the command for everyone."},
	{Key: "auto_update", Type: "string", Doc: "AutoUpdate is acp-kit/autoupdate's mode: \"off\", \"notify\", \"stage\" (default) or \"auto\". It needs UpdateOwnerIDs: offers are a DM to the owners, and only their reactions decide. \"auto\" is refused (downgraded to stage) on a fleet-managed host, where an offer is dist.lock drift and approval runs UpdateConvergeCmd. AutoUpdateQuietHours (\"HH:MM-HH:MM\", local) holds applies."},
	{Key: "auto_update_quiet_hours", Type: "string", Doc: "AutoUpdate is acp-kit/autoupdate's mode: \"off\", \"notify\", \"stage\" (default) or \"auto\". It needs UpdateOwnerIDs: offers are a DM to the owners, and only their reactions decide. \"auto\" is refused (downgraded to stage) on a fleet-managed host, where an offer is dist.lock drift and approval runs UpdateConvergeCmd. AutoUpdateQuietHours (\"HH:MM-HH:MM\", local) holds applies."},
	{Key: "fleet_managed", Type: "bool", Doc: "FleetManaged marks a host whose versions are owned by converge/dist.lock: `!update` then runs UpdateConvergeCmd (a shell command) instead of updating binaries in place, and refuses when it is unset. FleetLockFile, if set, is that host's dist.lock, shown by `!update --check` and diffed in the report. Setting either FleetLockFile or UpdateConvergeCmd implies FleetManaged."},
	{Key: "fleet_lock_file", Type: "string", Doc: "FleetManaged marks a host whose versions are owned by converge/dist.lock: `!update` then runs UpdateConvergeCmd (a shell command) instead of updating binaries in place, and refuses when it is unset. FleetLockFile, if set, is that host's dist.lock, shown by `!update --check` and diffed in the report. Setting either FleetLockFile or UpdateConvergeCmd implies FleetManaged."},
	{Key: "update_converge_cmd", Type: "string", Doc: "FleetManaged marks a host whose versions are owned by converge/dist.lock: `!update` then runs UpdateConvergeCmd (a shell command) instead of updating binaries in place, and refuses when it is unset. FleetLockFile, if set, is that host's dist.lock, shown by `!update --check` and diffed in the report. Setting either FleetLockFile or UpdateConvergeCmd implies FleetManaged."},
	{Key: "agent_cmd", Type: "[]string", Doc: "AgentCmd is the argv used to spawn the ACP agent. Default: [\"fir\", \"--mode\", \"acp\"]."},
	{Key: "state_dir", Type: "string", Doc: "StateDir roots per-conversation state. Each conversation gets a stable cwd so agent state (e.g. .fir/) survives restarts and idle GC. Default $XDG_STATE_HOME/zulip-acp."},
	{Key: "session_scope", Type: "string", Doc: "SessionScope picks what one agent session serves: \"thread\" (default) = one session per topic or DM; \"thread_user\" = one session per (topic, sender). See SessionScopeThreadUser."},
	{Key: "cwd_mode", Type: "string", Doc: "CwdMode picks the cwd the relay sends to the agent: \"local\" (default) = a directory under StateDir on this host; \"agent\" = an opaque placeholder (AgentCwdPlaceholder), and the agent side picks the real directory. See CwdModeAgent."},
	{Key: "session_idle_timeout_seconds", Type: "int", Doc: "SessionIdleTimeoutSeconds GCs idle sessions. 0 = 30 minutes."},
	{Key: "no_progress_timeout_seconds", Type: "int", Doc: "NoProgressTimeoutSeconds cuts a turn that has gone silent: no agent output and no tool activity for this long. Tool calls count as progress, so a legitimately long tool is never cut. 0 = 2 minutes."},
	{Key: "prompt_timeout_seconds", Type: "int", Doc: "PromptTimeoutSeconds is the absolute ceiling on one agent turn, enforced regardless of progress. 0 (unset) = DefaultTurnCeiling (2 hours); a negative value disables the ceiling. The guard that normally fires is NoProgressTimeoutSeconds; this one stops a turn that keeps making progress for hours."},
	{Key: "reload_drain_seconds", Type: "int", Doc: "ReloadDrainSeconds bounds how long a SIGHUP graceful reload waits for in-flight turns before it cancels them and re-execs. 0 = reload.DefaultReloadDrain (5 minutes). The -reload-drain-deadline flag, when given, wins."},
	{Key: "system_prompt", Type: "string", Doc: "SystemPrompt is appended to the built-in Zulip-formatting instructions and injected into every ACP session."},
	{Key: "disable_system_prompt", Type: "bool", Doc: "DisableSystemPrompt skips system-prompt injection entirely, including the built-in formatting block."},
	{Key: "hide_thinking", Type: "bool", Doc: "HideThinking suppresses agent thought chunks from the posted message."},
	{Key: "silent_sentinel", Type: "string", Doc: "SilentSentinel is the exact agent output that means \"do not reply\". Only consulted for ambient (non-mention) turns. Default \"<<SILENT>>\"."},
	{Key: "max_message_chars", Type: "int", Doc: "MaxMessageChars budgets one Zulip message, in CODE POINTS. 0 uses rollover.DefaultBudget (9500), deliberately below Zulip's hard 10000 so a server-side change in counting cannot cost output."},
	{Key: "seal_marker", Type: "string", Doc: "SealMarker closes a message that has rolled over. This is a UX choice, not a protocol one — change it freely."},
	{Key: "continuation_marker", Type: "string", Doc: "ContinuationMarker opens every message after the first."},
	{Key: "edit_interval_ms", Type: "int", Doc: "EditIntervalMs coalesces streaming edits. 0 = 300ms."},
	{Key: "stream_edits", Type: "bool", Doc: "StreamEdits publishes the answer AS IT ARRIVES, by editing the relay's own message every EditInterval. Unset = true, which is the behaviour everyone has today. Set it to false for \"quiet\" (batch) mode: nothing is edited during the turn and the whole answer is published once, when the turn closes. The web and desktop clients re-render a message on every edit, so a long turn visibly flickers; quiet mode trades live streaming for a still screen. EditIntervalMs is then unused: there is no coalescing tick left to set the period of. It is a pointer so \"unset\" and an explicit false stay distinguishable, exactly like RepostOnClose. Quiet mode also turns the placeholder spinner OFF by default — see SpinnerIntervalMs. Animating a placeholder for a whole turn with no streamed text under it is the WORST case, not a compromise, so the two settings are resolved together."},
	{Key: "topic_status", Type: "TopicStatusMode", Doc: "TopicStatus shows in the topic list whether agent work is live in a topic: \"emoji\" (the default), \"resolve\" or \"off\". The old boolean form still loads: true is the default, false is off. \"emoji\" puts StatusBusy in front of the topic name while a turn runs and StatusQuestion while the agent waits for the user; an idle topic has no prefix. A plain topic move posts no notice (measured, Zulip 12.2). \"resolve\" uses Zulip's own resolve mark (✔): resolved when no turn runs and nothing is scheduled. Notification Bot posts a \"marked as resolved\" notice for every resolve, and no API flag suppresses it. Use it only when is:resolved matters to you."},
	{Key: "status_busy", Type: "string", Doc: "StatusBusy and StatusQuestion are the \"emoji\" mode glyphs. Unset = DefaultStatusBusy / DefaultStatusQuestion. Literal Unicode: a topic name does not expand :name: emoji."},
	{Key: "status_question", Type: "string", Doc: "StatusBusy and StatusQuestion are the \"emoji\" mode glyphs. Unset = DefaultStatusBusy / DefaultStatusQuestion. Literal Unicode: a topic name does not expand :name: emoji."},
	{Key: "spinner_interval_ms", Type: "int", Doc: "SpinnerIntervalMs animates the \"Thinking…\" placeholder until the first chunk of the answer replaces it. Unset = 900ms when StreamEdits is on, and 0 when it is off. An explicit 0 means DO NOT ANIMATE: the placeholder is posted once and never edited again — no spinner goroutine is started at all. An explicit positive value is honoured in quiet mode too, which is then the only edit the relay makes during a turn; that is a deliberate choice, so it is not overridden. It is a pointer so \"unset\" and an explicit 0 stay distinguishable, exactly like AckEmoji."},
	{Key: "react_settle_ms", Type: "int", Doc: "ReactSettleMs is the pause between the echo of the relay's own message and the first reaction the relay pre-adds to it. The echo proves the server fanned the message out, not that a client rendered it: the macOS client drops a reaction that arrives a few ms after the message, until a reload. Unset = 200ms; 0 = no pause. It is a pointer so \"unset\" and an explicit 0 stay distinguishable."},
	{Key: "ack_emoji", Type: "string", Doc: "AckEmoji names the Zulip emoji reaction the relay adds to a message it has accepted, and removes when the turn ends. Unset = DefaultAckEmoji (\"eyes\"); an explicit \"\" disables the acknowledgement entirely. It is a pointer precisely so those two cases stay distinguishable."},
	{Key: "repost_on_close", Type: "bool", Doc: "RepostOnClose re-posts the finished answer as NEW messages at the end of a streamed turn, deleting the placeholder-seeded originals. Zulip generates a mobile push notification when a message is CREATED and never when it is edited, so without this every push reads \"Thinking…\". Unset = true; set it to false to keep the streamed messages exactly where they are (older clients, or a realm where the bot may not delete its own messages — though the relay also disables reposting by itself the first time a delete is refused)."},
	{Key: "reactions", Type: "bool", Doc: "Reactions delivers Zulip emoji reactions to the agent as a synthetic user turn (\"[reaction] Ada added :tada: to …\"), additions and removals alike. Unset = TRUE, and opting OUT is the deliberate act. It only ever fires in a conversation the relay is ALREADY engaged in, for a user the allowlist already permits — a deliberate signal from someone mid-conversation, not a new way in — it never creates a conversation or a session, and a burst of reactions is coalesced into ONE turn, so a pile-on costs what a single reaction costs. Set it to false if you do not want a stray :+1: to cost a turn at all."},
	{Key: "widgets", Type: "bool", Doc: "Widgets tells the agent that this realm runs the zulip-lite widgets patch, so a bot message can carry a live, sandboxed HTML widget or an MCP App. When true, the system prompt gets a short \"Inline widgets\" note and the bundled widgets skill is listed. Default false: on a stock realm the widget shows only as a collapsed spoiler, so the agent must not offer it there."},
	{Key: "quick_models", Type: "list of objects", Doc: "QuickModels is the emoji model switcher: a short list of provider/account/model combos, each bound to one emoji. A reaction with QuickModelsMenuEmoji on any relay message posts a menu; a shortlist emoji switches that topic; QuickModelsSweepEmoji on the confirmation applies the choice to every session and to new topics. The relay handles all of it; the agent never sees these reactions. Empty = off. At most MaxQuickModels entries."},
	{Key: "quick_models[].emoji", Type: "string", Doc: "Emoji is the bare Zulip emoji name, e.g. \"fish\"."},
	{Key: "quick_models[].model", Type: "string", Doc: "Model is the agent model id, e.g. \"sakana/ultra\"."},
	{Key: "quick_models[].label", Type: "string", Doc: "Label is the human name shown in the menu. Unset = Model."},
	{Key: "quick_models_menu_emoji", Type: "string", Doc: "QuickModelsMenuEmoji opens the switcher menu. Unset = DefaultQuickModelsMenuEmoji (\"gear\")."},
	{Key: "quick_models_sweep_emoji", Type: "string", Doc: "QuickModelsSweepEmoji, tapped on a switch confirmation, applies that model to all sessions. Unset = DefaultQuickModelsSweepEmoji (\"www\")."},
	{Key: "catchup_max_age_seconds", Type: "int", Doc: "CatchupMaxAgeSeconds bounds the offline catch-up. On a cold start the relay reads the messages that arrived while it was down and gives each topic ONE collapsed turn for them; messages older than this are skipped with a one-line notice in the topic. Unset = DefaultCatchupMaxAge (24h); an explicit 0 turns the catch-up off. It is a pointer so those two cases stay distinguishable."},
	{Key: "archive_channel", Type: "string", Doc: "ArchiveChannel names the channel a topic is MOVED to when somebody archives it — by reacting :wastebasket: to the relay's last message, or by typing `!archive`. Unset = DefaultArchiveChannel (\"archive\"); an explicit \"\" turns the feature off. It is a pointer so those two cases stay distinguishable, exactly like AckEmoji. The destination MUST be a channel the relay does not serve. That is what makes an archive final: an unserved channel is outside the allowlist by construction, so the topic cannot re-engage the relay, and recovery is one move back. The relay checks this at startup — along with whether the channel exists and whether realm policy lets the bot move messages between channels — and disables the feature with a log line if any of it does not hold, rather than failing at the moment someone taps the emoji. Nothing is deleted: the topic and its messages travel intact, and the conversation's state/convs/<id>/ directory stays on disk."},
	{Key: "inbound_attachments", Type: "bool", Doc: "InboundAttachments downloads the files a human attaches to a message into the conversation's working directory (`inbox/`) and tells the agent where they are — with images additionally sent as ACP image content blocks when the agent advertises support. Unset = TRUE. A Zulip message carries a LINK, never a file, and the bytes sit behind an authenticated endpoint, so without this an agent asked about an attached photo can only say it cannot see it. Set it to false to keep the relay from fetching anything a message points at. The files persist: they live in the conversation's state directory, like everything else the conversation owns, and nothing deletes them. `!new` mints a fresh conversation with a fresh directory, so the new session starts with an empty inbox while the old files stay on disk."},
	{Key: "max_attachment_bytes", Type: "int64", Doc: "MaxAttachmentBytes caps ONE inbound attachment and MaxAttachmentTotalBytes caps a whole message's worth. 0 uses the handler defaults (20 MB and 60 MB). Anything over cap is SKIPPED and named in the prompt — the turn still happens, and the agent is told what it did not get, so it can ask for a smaller file instead of hallucinating about one it never saw."},
	{Key: "max_attachment_total_bytes", Type: "int64", Doc: "MaxAttachmentBytes caps ONE inbound attachment and MaxAttachmentTotalBytes caps a whole message's worth. 0 uses the handler defaults (20 MB and 60 MB). Anything over cap is SKIPPED and named in the prompt — the turn still happens, and the agent is told what it did not get, so it can ask for a smaller file instead of hallucinating about one it never saw."},
	{Key: "max_inline_image_pixels", Type: "int", Doc: "MaxInlineImagePixels caps the LONG EDGE, in pixels, of an image inlined into the prompt. Unset = 1568, Anthropic's recommended maximum useful dimension. 0 disables downscaling. A byte cap is not a pixel cap, and the providers enforce the latter: Anthropic refuses a whole request carrying several images when any one of them exceeds 2000 pixels on a side. A phone photo is 5712x4284 and compresses small enough to pass every byte budget, so without this it kills the turn — and every later turn in the topic, because the oversized image stays in the session's history. Only the INLINED copy is downscaled. The file in `inbox/` is always the original, because an agent doing detail work reads it from disk."},
	{Key: "relay_mcp", Type: "bool", Doc: "RelayMCP enables the agent→relay loopback: the relay hosts an MCP server on a private unix socket and advertises it to the agent, so the agent can read its own status, switch model, post out of band, and schedule prompts back into this conversation. Default FALSE, and deliberately so. It hands the agent a way to speak into the chat outside a turn and to arm work that runs with no human watching, which is a real widening of what a prompt-injected agent could do. Turn it on knowingly."},
	{Key: "max_schedules_per_conv", Type: "int", Doc: "MaxSchedulesPerConv, MaxSchedulesTotal and MaxScheduleDepth bound scheduled prompts. 0 uses acp-kit/schedule's defaults (10 / 100 / 3). MaxScheduleDepth is the important one: it caps how long a schedule→turn→schedule chain can get, so recursion always terminates."},
	{Key: "max_schedules_total", Type: "int", Doc: "MaxSchedulesPerConv, MaxSchedulesTotal and MaxScheduleDepth bound scheduled prompts. 0 uses acp-kit/schedule's defaults (10 / 100 / 3). MaxScheduleDepth is the important one: it caps how long a schedule→turn→schedule chain can get, so recursion always terminates."},
	{Key: "max_schedule_depth", Type: "int", Doc: "MaxSchedulesPerConv, MaxSchedulesTotal and MaxScheduleDepth bound scheduled prompts. 0 uses acp-kit/schedule's defaults (10 / 100 / 3). MaxScheduleDepth is the important one: it caps how long a schedule→turn→schedule chain can get, so recursion always terminates."},
	{Key: "min_schedule_interval_seconds", Type: "int", Doc: "MinScheduleIntervalSeconds floors a repeating schedule. 0 uses acp-kit/schedule's default of 60s."},
	{Key: "mcp_apps", Type: "object", Doc: "MCPApps hosts MCP Apps (internal/mcpapps): a tool call that declares a `ui://` resource gets a link in the topic to a page the relay serves. Off unless mcp_apps.public_url is set. See docs/mcp-apps-design.md."},
	{Key: "mcp_apps.public_url", Type: "string", Doc: "PublicURL is the origin a reverse proxy serves the listener at, for example \"https://apps.example.com\". REQUIRED: without it the feature is off, because a link must point somewhere a phone can reach."},
	{Key: "mcp_apps.content_url", Type: "string", Doc: "ContentURL is an optional second origin for the app HTML."},
	{Key: "mcp_apps.listen", Type: "string", Doc: "Listen is the address the HTTP listener binds. It must be a loopback address: the relay never listens on the network itself."},
	{Key: "mcp_apps.ttl_hours", Type: "int", Doc: "TTLHours is how long an app link stays valid. 0 is 24."},
	{Key: "files", Type: "object", Doc: "Files turns on large out-of-band `send_file` uploads: the agent's client PUTs a file to a one-shot relay endpoint, which forwards it to Zulip. Off unless files.public_url is set. Inline `send_file` and the attachment download tools need only relay_mcp. See docs/zulip-acp-design.md."},
	{Key: "files.public_url", Type: "string", Doc: "PublicURL is the https origin a reverse proxy serves the upload listener at, for example \"https://up.example.com\". REQUIRED for large uploads: the agent's client must reach it."},
	{Key: "files.listen", Type: "string", Doc: "Listen is the address the upload listener binds. It must be a loopback address."},
	{Key: "files.max_mb", Type: "int", Doc: "MaxMB is the largest file `send_file` takes, in MiB. 0 is 25. Keep it at or under the realm's max_file_upload_size."},
	{Key: "delete", Type: "object", Doc: "Delete names a second Zulip bot that performs the delete-emoji topic delete, so the relay bot need not be an administrator. Absent = the relay bot tries itself. See Delete and docs/zulip-acp-design.md."},
	{Key: "delete.bot_email", Type: "string", Doc: "BotEmail is the delete bot's Zulip e-mail."},
	{Key: "delete.key_file", Type: "string", Doc: "KeyFile is the absolute path of a file that holds the delete bot's API key. It must not be readable by group or others."},
	{Key: "delete.scope", Type: "string", Doc: "Scope is what a delete may remove. Only \"topic\" (the default)."},
	{Key: "delete.owners_only", Type: "bool", Doc: "OwnersOnly lets only update_owner_ids confirm a delete. Unset = true."},
	{Key: "delete.emoji", Type: "string", Doc: "Emoji is the bare Zulip emoji name that confirms a delete on the archive warning. Unset = DefaultDeleteEmoji."},
}
